#!/usr/bin/env node
// Generates src/components/index.ts and src/components/examples.ts from the component folders.
// A folder counts once it has <name>.ts, <name>.css and <name>.examples.ts. `--check` fails if the
// generated files are stale (lint).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const CATEGORY_ORDER = ['layout', 'actions', 'forms', 'data', 'navigation', 'feedback', 'overlays', 'content', 'ai'];
const dir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../src/components');
const camel = (s) => s.replace(/-([a-z])/g, (_, c) => c.toUpperCase());
// Component folders whose camel-cased name is a reserved word export `<name>Component` instead.
const RESERVED = new Set(['switch', 'default', 'delete', 'new', 'class', 'function', 'var', 'case', 'in', 'import', 'export']);

const components = fs
  .readdirSync(dir, { withFileTypes: true })
  .filter((e) => e.isDirectory())
  .map((e) => e.name)
  .filter((name) => ['.ts', '.css', '.examples.ts'].every((ext) => fs.existsSync(path.join(dir, name, `${name}${ext}`))))
  .map((name) => {
    const src = fs.readFileSync(path.join(dir, name, `${name}.ts`), 'utf8');
    const category = /category:\s*'([a-z]+)'/.exec(src)?.[1] ?? 'content';
    const key = camel(name);
    return { name, key, id: RESERVED.has(key) ? `${key}Component` : key, category };
  })
  .sort((a, b) => CATEGORY_ORDER.indexOf(a.category) - CATEGORY_ORDER.indexOf(b.category) || a.name.localeCompare(b.name));

const header = '// Generated by scripts/generate-registry.mjs from the component folders. Do not edit.\n';
const index = `${header}${components.map((c) => `import { ${c.id} } from './${c.name}/${c.name}';`).join('\n')}

/** Every component, in catalog order (by category, then name). */
export const componentList = [${components.map((c) => c.id).join(', ')}] as const;

/** Component tokens keyed by camel-cased component name (\`tool-call\` → \`toolCall\`). */
export const componentTokens = {
${components.map((c) => `  ${c.key}: ${c.id}.tokens,`).join('\n')}
};
`;
const examples = `${header}import type { ComponentExamples } from '../contract/component';
${components.map((c) => `import ${c.id} from './${c.name}/${c.name}.examples';`).join('\n')}

/** Examples for every component. Node-only (imported by the build entry, not the browser entry). */
export const componentExamples: ComponentExamples[] = [${components.map((c) => c.id).join(', ')}];
`;

const files = { 'index.ts': index, 'examples.ts': examples };
if (process.argv.includes('--check')) {
  const stale = Object.entries(files).filter(([f, c]) => fs.readFileSync(path.join(dir, f), 'utf8') !== c);
  if (stale.length) {
    console.error(`src/components/${stale.map(([f]) => f).join(', ')} stale; run node scripts/generate-registry.mjs`);
    process.exit(1);
  }
} else {
  for (const [f, c] of Object.entries(files)) fs.writeFileSync(path.join(dir, f), c);
  console.log(`registry: ${components.length} components`);
}
